"""Map Rasa dialogue stack and tracker state to A2A task states."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any, Dict, List, Optional

from a2a.types import TaskState

from rasa.shared.constants import RASA_DEFAULT_FLOW_PATTERN_PREFIX
from rasa.shared.core.constants import (
    ACTION_AGENT_REQUEST_USER_INPUT_NAME,
    ACTION_LISTEN_NAME,
)
from rasa.shared.core.events import FlowCompleted, FlowInterrupted, FlowStarted

if TYPE_CHECKING:
    from rasa.shared.core.trackers import DialogueStateTracker


@dataclass(frozen=True)
class TaskStateMappingResult:
    """Result of mapping Rasa dialogue state or auth middleware to an A2A task state."""

    state: TaskState
    reason: Optional[str] = None
    error_type: Optional[str] = None
    error_info: Optional[Dict[str, Any]] = None
    canceled_name: Optional[str] = None
    canceled_frames: Optional[List[str]] = None

    @property
    def is_terminal(self) -> bool:
        """Return whether the mapped state ends the current task cycle."""
        return self.state in {
            TaskState.completed,
            TaskState.rejected,
            TaskState.failed,
            TaskState.canceled,
        }


class TaskStateMapper:
    """Maps Rasa tracker/stack state to A2A ``TaskState`` values.

    Use :meth:`map` after message processing (tracker-based states).
    Use :meth:`map_auth_required` or ``map(tracker, auth_valid=False)`` from
    auth middleware when ``a2a_server.auth`` rejects the inbound request
    (orchestrator credentials only — not end-user auth).
    """

    @classmethod
    def map_auth_required(cls) -> TaskStateMappingResult:
        """Return ``auth_required`` for orchestrator auth middleware (T12).

        Call when ``a2a_server.auth`` validation fails (missing/invalid bearer
        token on the A2A HTTP request). This authenticates the **orchestrator**,
        not the end user. End-user auth is the orchestrator's responsibility;
        forward any needed context via A2A metadata/DataParts.
        """
        return TaskStateMappingResult(state=TaskState.auth_required)

    def map(
        self,
        tracker: "DialogueStateTracker",
        *,
        auth_valid: bool = True,
        include_conversation_repair: bool = True,
    ) -> TaskStateMappingResult:
        """Derive the A2A task state after a message has been processed.

        Args:
            tracker: Current dialogue tracker after processing.
            auth_valid: When ``False``, map to ``auth_required`` regardless of
                tracker state. Auth middleware should set this before calling
                ``map`` when a bearer token is missing or invalid.
            include_conversation_repair: When ``True``, an active
                ``CompletedPatternFlowStackFrame`` at ``action_listen`` maps to
                ``input_required`` only when no user flow finished this turn
                (conversation repair). When a user flow emitted
                ``FlowCompleted`` this turn, map to ``completed`` instead (rule 5).

        ``ConversationInactive`` and ``tracker.inactive`` are intentionally ignored:
        A2A contexts stay resumable on the same ``contextId``/``sender_id``; task state
        reflects dialogue stack and latest action only.

        Priority order:
        1. ``auth_required`` when ``auth_valid`` is ``False``
        2. ``rejected`` when ``CannotHandlePatternFlowStackFrame`` is active
        3. ``failed`` when ``InternalErrorPatternFlowStackFrame`` is active
        4. ``canceled`` when ``CancelPatternFlowStackFrame`` is active
        5. ``completed`` when a user-facing flow emitted ``FlowCompleted`` this turn,
           no user flows remain on the stack, and the bot waits for user input
           (even when ``pattern_completed`` is active at ``action_listen``)
        6. ``input_required`` when ``CompletedPatternFlowStackFrame`` is active,
           no user flows remain on the stack, ``include_conversation_repair`` is
           ``True``, the bot waits for user input, and no user flow completed this turn
        7. ``completed`` when ``CompletedPatternFlowStackFrame`` is active and
           no user flows remain on the stack (including when conversation repair
           is disabled)
        8. ``input_required`` when the last action waits for user input
        9. ``working`` otherwise
        """
        from rasa.dialogue_understanding.patterns.cancel import (
            CancelPatternFlowStackFrame,
        )
        from rasa.dialogue_understanding.patterns.cannot_handle import (
            CannotHandlePatternFlowStackFrame,
        )
        from rasa.dialogue_understanding.patterns.completed import (
            CompletedPatternFlowStackFrame,
        )
        from rasa.dialogue_understanding.patterns.continue_interrupted import (
            ContinueInterruptedPatternFlowStackFrame,
        )
        from rasa.dialogue_understanding.patterns.internal_error import (
            InternalErrorPatternFlowStackFrame,
        )
        from rasa.dialogue_understanding.stack.utils import (
            get_active_pattern_frame,
            is_pattern_active,
            user_flows_on_the_stack,
        )

        if not auth_valid:
            return self.map_auth_required()

        stack = tracker.stack

        cannot_handle = get_active_pattern_frame(
            stack, CannotHandlePatternFlowStackFrame
        )
        if isinstance(cannot_handle, CannotHandlePatternFlowStackFrame):
            return TaskStateMappingResult(
                state=TaskState.rejected,
                reason=cannot_handle.reason,
            )

        internal_error = get_active_pattern_frame(
            stack, InternalErrorPatternFlowStackFrame
        )
        if isinstance(internal_error, InternalErrorPatternFlowStackFrame):
            return TaskStateMappingResult(
                state=TaskState.failed,
                error_type=internal_error.error_type,
                error_info=dict(internal_error.info),
            )

        cancel_frame = get_active_pattern_frame(stack, CancelPatternFlowStackFrame)
        if isinstance(cancel_frame, CancelPatternFlowStackFrame):
            return TaskStateMappingResult(
                state=TaskState.canceled,
                canceled_name=cancel_frame.canceled_name or None,
                canceled_frames=list(cancel_frame.canceled_frames),
            )

        latest_action = tracker.latest_action_name
        waiting_for_user_input = latest_action in {
            ACTION_LISTEN_NAME,
            ACTION_AGENT_REQUEST_USER_INPUT_NAME,
        }
        user_flow_completed_this_turn = _user_flow_completed_this_turn(tracker)

        if (
            waiting_for_user_input
            and not user_flows_on_the_stack(stack)
            and user_flow_completed_this_turn
            and not _flow_was_interrupted_this_turn(tracker)
            and not is_pattern_active(stack, ContinueInterruptedPatternFlowStackFrame)
        ):
            return TaskStateMappingResult(state=TaskState.completed)

        if is_pattern_active(
            stack, CompletedPatternFlowStackFrame
        ) and not user_flows_on_the_stack(stack):
            if (
                include_conversation_repair
                and waiting_for_user_input
                and not user_flow_completed_this_turn
            ):
                return TaskStateMappingResult(state=TaskState.input_required)
            return TaskStateMappingResult(state=TaskState.completed)

        if waiting_for_user_input:
            return TaskStateMappingResult(state=TaskState.input_required)

        return TaskStateMappingResult(state=TaskState.working)


def _user_flow_completed_this_turn(tracker: "DialogueStateTracker") -> bool:
    """Return whether a user-facing flow emitted ``FlowCompleted`` this turn.

    Scanning in reverse avoids treating an earlier ``FlowCompleted`` as terminal
    when a user flow was started again later in the same turn.
    """
    for event in reversed(tracker.get_last_turn_events()):
        if isinstance(event, FlowCompleted) and _is_user_flow_id(event.flow_id):
            return True
        if isinstance(event, FlowStarted) and _is_user_flow_id(event.flow_id):
            return False
    return False


def _is_user_flow_id(flow_id: str) -> bool:
    return not flow_id.startswith(RASA_DEFAULT_FLOW_PATTERN_PREFIX)


def _flow_was_interrupted_this_turn(tracker: "DialogueStateTracker") -> bool:
    """Return whether a user flow was interrupted during the current turn."""
    return any(
        isinstance(event, FlowInterrupted) for event in tracker.get_last_turn_events()
    )
